function countSyllables(word){
  word=String(word).toLowerCase().replace(/[^a-z]/g,'');
  if(!word) return 0;
  if(word.length<=3) return 1;
  word=word.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/,'');
  word=word.replace(/^y/,'');
  var m=word.match(/[aeiouy]+/g);
  return m?m.length:1;
}
function stats(text){
  var words=String(text).match(/[A-Za-z0-9']+/g)||[];
  var nw=words.length; if(!nw) return {words:0, sentences:0, syllables:0};
  var ns=0; for(var i=0;i<nw;i++) ns+=countSyllables(words[i]);
  var sentences=String(text).split(/[.!?]+/).filter(function(s){return s.trim().length;}).length;
  if(!sentences) sentences=1;
  return {words:nw, sentences:sentences, syllables:ns};
}
function flesch(text){ var s=stats(text); if(!s.words) return NaN; return 206.835 - 1.015*(s.words/s.sentences) - 84.6*(s.syllables/s.words); }
function kincaid(text){ var s=stats(text); if(!s.words) return NaN; return 0.39*(s.words/s.sentences) + 11.8*(s.syllables/s.words) - 15.59; }
var EXPORTS={ countSyllables:countSyllables, stats:stats, flesch:flesch, kincaid:kincaid };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ReadingLevelForgePure = EXPORTS; }
